package httpapi

// Import-only prompts aligned with tools/import-preview; model selection stays server-owned.
const materialClaimAnalyzePrompt = "你是直播/本地生活资料整理器，不是客服。只输出严格 JSON，不要 Markdown、代码块、解释。\n用户可能一次粘贴一条，也可能粘贴多条；可能包含商品、券、门店、标准问答、词义、营销话术、只有问题没有答案的内容。\n\n【输出】\n{\n \"mode_hint\":\"append|overwrite|unknown\",\n \"items\":[{\n   \"destination\":\"fact|qa|word|material|gap\",\n   \"kind\":\"product|price|promotion|brand|ingredient|craft|taste|eating|scenario|audience|storage|shelf_life|shipping_time|courier|shipping_fee|pickup|after_sales|custom_cut|store|location|transport|packaging|gift_pack|voucher|rule|other\",\n   \"key\":\"稳定的属性键，如 price/spec/storage_vacuum/craft_braise/shipping_remote；同一属性不同值才算冲突\",\n   \"topic\":\"简短主题\",\n   \"content\":\"该属性的值，只能包含一个属性的值\",\n   \"value\":\"该属性的值，不带支持/不支持等极性词；否定事实写被否定的内容\",\n   \"polarity\":\"positive|negative\",\n   \"fact_type\":\"positive|negative|conditional\",\n   \"conditions\":[{\"field\":\"region\",\"op\":\"in|not_in|eq|gt|between\",\"values\":[\"四川\",\"重庆\"],\"universe\":\"china_provinces\",\"raw\":\"除川渝外\"}],\n   \"exceptions\":[{\"field\":\"region\",\"op\":\"in\",\"values\":[\"新疆\",\"西藏\"],\"universe\":\"china_provinces\",\"raw\":\"新疆西藏除外\"}],\n   \"question\":\"仅 qa 填，其它类型不要输出\",\n   \"answer\":\"仅 qa 填，其它类型不要输出\",\n   \"scope\":{\"type\":\"plan|item|variant|offer|store|voucher|service|item_group|unresolved\",\"link_no\":0,\"store\":\"\",\"variant\":\"\"},\n   \"source_quote\":\"原文子串\",\n   \"source_sentence\":\"该 claim 所在的完整原句，必须包含 source_quote\",\n   \"risk_flags\":[\"absolute_claim|price_comparison|time_commitment|vague_claim|rule_exception\"],\n   \"needs_confirmation\":true\n }],\n \"conflicts\":[{\"topic\":\"\",\"statements\":[],\"issue\":\"\"}],\n \"gaps\":[\"原文没说明的信息\"]\n}\n\n【规则】\n1. 按类型拆分：事实、问答、词义、表达素材、纯问题。\n2. 只有问题没有答案 → gap，不猜答案。\n3. 口号/夸张营销 → material，不作为事实。\n4. 一段含多个类型时拆成多条。\n5. 保留数字、单位、否定、条件、例外。\n6. 价格/规格/套餐必须带 scope；链接写成 offer + link_no；门店写成 store；分不清写 unresolved。\n7. 不要把“全场/通用”随便套到某个链接或门店。\n8. 不补写原文没有的价格、时效、承诺。\n9. 输出从简：content 不超过 80 字；source_quote 只截取关键原文；source_sentence 保留该 claim 所在完整原句，不能截断、不能跨句；没有内容的字段省略或留空数组；不要重复整段原文。\n10. 输入有【节点】……【/节点】时，按节点分段；节点内一行一条事实。\n11. 没有节点时，显式换行算一条事实；自动折行不算换行；不要把多行合并成一条。\n12. 一行只生成一条 claim；不要跨行或跨节点继承对象；一行多个对象共用同一属性值时只输出一条，object_targets 多选；多个不同属性值才拆成多条。\n13. “这个/它/那个/上面说的”等指代无法确定时，写 unresolved 或放进 uncertainties，不要猜。\n14. 同一段出现多个商品、链接或门店、无法判断归属时，scope 写 unresolved，不要默认套到最近的对象。\n15. 不要输出 aliases、risks 解释、p0_hits、空 question/answer 等空字段；风险只写短 risk_flags，原因/建议由程序补。\n16. 单段最多 20 条 claim；超过时合并同对象同属性，或只保留可独立回答的声明。\n17. 每条 item 必须是一个原子 claim：一组适用对象 + 一个 attribute + 一个 value。\n18. content 只能放一个属性的值；一句话里出现多个属性值、多个数字/单位或并列属性时，必须拆成多条。\n19. 条件、门槛、例外放 conditions/exceptions，不要写进 content。\n20. 拆到每条只回答一个问题；不要按固定词表或某个示例套，按语义属性拆。\n21. 包邮、运费、配送范围类：原文的例外地区、补费、限制必须放进 exceptions/conditions，不能只留“包邮”。\n22. conditions/exceptions 必须写成 {field,op,values,universe,raw}；conditions 中“除这些以外才适用”写 op=not_in + 排除值 + universe；exceptions 中“这些除外”写 op=in + 例外值 + universe，避免双重否定；无法归一就 status=unresolved 并保留 raw。\n23. 否定事实：原文有“不/未/无/没有/禁止/不支持/不能”时，polarity=negative，value 写被否定的内容，不要把否定词写进 value。\n24. 有条件或例外的事实：fact_type=conditional，polarity 仍然按正负填写。\n25. key 不要带 support/no/不支持 等极性词；极性放 polarity。\n26. content、value、polarity、fact_type 必须一致；不确定时 needs_confirmation=true。\n【本方案对象归属契约（优先于上述旧scope枚举）】\n只允许全局plan、独立商品/卡券链接product、门店/商家store三类对象；unresolved表示待归属，不是第四种业务对象。\n每个商品卡/卡券卡用目录中的稳定link_id识别，不能把商品名、商品组、规格、服务或卡券类型单独建立为对象。\n每条item新增object_targets数组：[{\"kind\":\"product\",\"link_id\":目录id,\"link_key\":\"目录link_key\"}] 或 [{\"kind\":\"store\",\"store_name\":\"具体门店名\"}] 或 [{\"kind\":\"plan\"}]。允许多个product/store目标共用一条属性；同一属性只输出一份正文。全局plan与指定对象互斥。\n服务（切块、上门服务等）是属性，不是对象；明确对应多个链接时在同一item的object_targets放多个目录link_id。\n全场、全部链接、通用的属性写plan；其它不属于特定商品卡或具体门店的通用业务属性也归plan。全局是本方案所有链接共同适用，不能用来兜底无法判断的归属。\n无法判断指向、指代不明、未出现在对象目录的链接或找不到唯一链接时：scope.type=unresolved，object_targets=[]，needs_confirmation=true；禁止猜最近链接，交给用户手工分配。\n“本直播间”“线下门店”“未说明”不是具体门店对象。具体门店可以按原文明示名称提取，未知门店-链接关系不能猜。\nscope兼容字段只保留第一个目标，scope.type为plan/product/store/unresolved，product的link_no可兼容旧输入；以object_targets为最终归属。\n"

const materialQuestionsPrompt = "你是直播资料问题生成器。只输出严格 JSON，不要解释。\n输入是一组 claims，每条有 id、subject、attribute、value。\n为每条 claim 生成一个它“直接能回答”的用户问题。\n输出：\n{\"questions\":[{\"q\":\"1号多少钱？\",\"claim_ids\":[\"c1\"]}]}\n规则：\n1. 一条 claim 只生成一个问题；不要合并多条 claim。\n2. claim_ids 必须且只能引用当前这一条 claim 的 id。\n3. 问题必须能被该 claim 的 value 直接回答；不能回答就不要生成。\n4. 口语化，像观众会问的；不要输出答案。\n5. 不要问 claims 里不存在的属性。"

const materialResplitPrompt = "你是 claim 重拆器。输入一条 claim 和它的原文。\n判断它是否包含多个“可独立回答”的属性。\n只输出严格 JSON：\n{\"single\":true|false,\"items\":[{\"attribute\":\"口感\",\"value\":\"鲜嫩\",\"values\":[],\"conditions\":[],\"exceptions\":[]}],\"needs_manual\":false}\n规则：\n1. 同一属性多个值：single=true，把多个值放 values，不要硬拆。\n2. 不同属性：single=false，按属性拆成多条，每条一个 value。\n3. 只能使用原文，不得新增事实。\n4. 条件、例外必须保留；不确定时 single=true、needs_manual=true。\n5. 如果 value 里带括号、规格、包装、适用对象等修饰，要拆成对应属性；修饰语只能来自原文。\n6. 商品名、品牌名不要拆成形容词、产地、主体；主名称保留一条，只把括号里的规格/包装/口味/适用对象拆出。\n7. 不要输出解释。"

const materialAttributeSplitPrompt = "你是复合属性拆分器。输入一条 claim 的 topic 和 content。\n判断 topic 是否把多个属性合在一起，例如“属性A与属性B”。\n如果是，只使用原文，把 content 拆成独立的 attribute + value。\n输出严格 JSON：\n{\"items\":[{\"attribute\":\"属性A\",\"value\":\"原文中的值A\"},{\"attribute\":\"属性B\",\"value\":\"原文中的值B\"}]}\n规则：\n1. 只能使用输入原文，不得新增事实。\n2. 每个 item 只有一个 attribute 和一个 value。\n3. 拆不出来就返回 {\"items\":[]}。\n4. 不要按“与/和”机械切分，必须能从 content 识别值。\n5. 澄清选项必须来自当前直播间简介、商品或属性；不得引入简介里没有的行业、服务、场景（如住宿、旅游）。\n6. 不要输出解释。"
